return items.map(item => {
  const data = item.json;
  const text = (data.raw_message || "").toLowerCase();

  let destination_queue = "Human Review";
  let escalation_flag = false;
  let escalation_reason = "";
  let billing_difference = null;

  if (data.category === "Bug Report" || data.category === "Incident/Outage") {
    destination_queue = "Engineering";
  } else if (data.category === "Feature Request") {
    destination_queue = "Product";
  } else if (data.category === "Billing Issue") {
    destination_queue = "Billing";
  } else if (data.category === "Technical Question") {
    destination_queue = "IT/Security";
  }

  const amounts = [...(data.raw_message || "").matchAll(/\$([\d,]+(?:\.\d{1,2})?)/g)]
    .map(m => parseFloat(m[1].replace(/,/g, "")));

  if (amounts.length >= 2) {
    billing_difference = Math.abs(amounts[0] - amounts[1]);
  }

  if ((data.confidence_score || 0) < 70) {
    escalation_flag = true;
    escalation_reason = "Low confidence classification";
  } else if (
    text.includes("outage") ||
    text.includes("down for all users") ||
    text.includes("multiple users affected") ||
    text.includes("multiple users") ||
    text.includes("dashboard stopped loading")
  ) {
    escalation_flag = true;
    escalation_reason = "Potential outage or multi-user impact";
  } else if (
    data.category === "Billing Issue" &&
    billing_difference !== null &&
    billing_difference > 500
  ) {
    escalation_flag = true;
    escalation_reason = "Billing discrepancy greater than $500";
  }

  if (escalation_flag) {
    destination_queue = "Escalation Queue";
  }

  return {
    json: {
      ...data,
      destination_queue,
      escalation_flag,
      escalation_reason,
      billing_difference
    }
  };
});

